<template>
  <main class="insight-page">
    <header class="insight-nav"><button class="insight-brand" type="button" @click="router.push('/system/user')"><span class="brand-mark"><i /><i /><i /></span><b class="brand-word">Sentiment</b></button><div class="mode-switch"><button :class="{ active: activeTab === 'chat' }" type="button" @click="activeTab = 'chat'">聊天</button><button :class="{ active: activeTab === 'work' }" type="button" @click="activeTab = 'work'">工作</button></div><button class="exit-button" type="button" @click="logout">退出登录</button></header>
    <section v-if="activeTab === 'chat'" class="chat-workspace"><div class="chat-intro"><span class="insight-kicker">SENTIMENT COPILOT · 预留模型接口</span><h1>{{ submitted ? '这份感受，值得被看见' : '准备好了，随时开始' }}</h1><p>{{ submitted ? '模型分析结果将在这里呈现。' : '把用户的真实反馈交给我，开始一次情绪探索。' }}</p></div><div v-if="result" class="result-card"><div><span class="result-label">情绪倾向</span><strong>{{ result.sentiment === 'positive' ? '正向' : result.sentiment === 'negative' ? '负向' : '中性' }}</strong></div><div><span class="result-label">置信度</span><strong>{{ result.score }}%</strong></div><p>{{ result.summary }}</p><div class="keyword-row"><span v-for="word in result.keywords" :key="word">{{ word }}</span></div></div><form class="chat-composer" @submit.prevent="submitMessage"><button class="plus-button" type="button" aria-label="添加商品信息" @click="showProductModal = true">＋</button><input v-model="message" :placeholder="language === 'zh' ? '问问用户的真实感受' : 'Ask about your users’ real feelings'" :disabled="loading" /><button class="language-button" type="button" :aria-label="language === 'zh' ? '切换英文' : '切换中文'" @click="toggleLanguage">{{ language === 'zh' ? '中' : 'EN' }}<span>⌄</span></button><button class="send-button" type="submit" :disabled="loading">{{ loading ? '…' : '↑' }}</button></form><p class="api-hint">{{ apiMessage }}</p></section>
    <section v-else class="work-panel"><span class="insight-kicker">WORKSPACE</span><h1>把洞察变成下一步行动。</h1><p>这里会承载后续的产品分析工作流。</p><button class="back-action" type="button" @click="activeTab = 'chat'">回到聊天 <span>→</span></button></section>
    <div v-if="showProductModal" class="modal-mask" @click.self="showProductModal = false"><form class="product-modal" @submit.prevent="saveProduct"><button class="modal-close" type="button" @click="showProductModal = false">×</button><span class="insight-kicker">PRODUCT CONTEXT</span><h2>补充商品信息</h2><p>让未来的模型更了解这次反馈属于谁。</p><label>商品名称<input v-model="product.name" required placeholder="例如：澄见智能水杯" /></label><label>商品类别<select v-model="product.category"><option value="">请选择商品类别</option><option>电子产品</option><option>生活用品</option><option>美妆个护</option><option>其他</option></select></label><label>用户评价<input v-model="product.rating" placeholder="例如：4.5 / 5" /></label><label>备注<textarea v-model="product.note" rows="3" placeholder="补充更多背景信息" /></label><button class="save-product" type="submit">保存并继续 <span>→</span></button></form></div>
  </main>
</template>
<script lang="ts" setup>
  import { ref } from 'vue';
  import { useRouter } from 'vue-router';
  import { predictSentiment, saveProductDraft, type ProductDraft, type SentimentPredictResult } from '/@/api/sentiment';
  import { useUserStore } from '/@/store/modules/user';
  const router = useRouter(); const userStore = useUserStore();
  const activeTab = ref<'chat' | 'work'>('chat'); const language = ref<'zh' | 'en'>('zh'); const message = ref(''); const loading = ref(false); const submitted = ref(false); const showProductModal = ref(false); const apiMessage = ref('输入内容后将调用情绪模型接口，当前接口尚未接入模型。'); const result = ref<SentimentPredictResult | null>(null);
  const product = ref<ProductDraft>({ name: '', category: '', rating: '', note: '' });
  function toggleLanguage() { language.value = language.value === 'zh' ? 'en' : 'zh'; apiMessage.value = language.value === 'zh' ? '已切换为中文输入' : 'Switched to English input'; }
  async function submitMessage() { if (!message.value.trim()) { apiMessage.value = language.value === 'zh' ? '先输入一段用户反馈，再发送给模型。' : 'Enter some user feedback before sending.'; return; } loading.value = true; submitted.value = true; apiMessage.value = '正在等待模型返回分析结果…'; try { result.value = await predictSentiment({ content: message.value, product: product.value.name ? product.value : undefined }); apiMessage.value = '分析完成，结果由模型接口返回。'; } catch { apiMessage.value = '模型接口暂未接入，已保留本次输入。'; result.value = { sentiment: 'neutral', score: 0, summary: '当前为前端壳子，连接模型服务后会在此展示真实分析结果。', keywords: ['等待模型', '接口预留'] }; } finally { loading.value = false; } }
  async function saveProduct() { try { await saveProductDraft(product.value); apiMessage.value = '商品信息已保存，后续预测将带上这份上下文。'; } catch { apiMessage.value = '商品信息已在当前页面保留，数据库接口待接入。'; } showProductModal.value = false; }
  async function logout() { await userStore.logout(true); }
</script>
