ard strong { color: #238d89; font-size: 24px; } .result-card p { margin: 18px 0; color: #557d83; font-size: 13px; line-height: 1.7; } .keyword-row { display: flex; gap: 8px; } .keyword-row span { padding: 6px 10px; border-radius: 999px; color: #4d8c88; background: #e7f6f0; font-size: 11px; } .work-panel { display: grid; min-height: calc(100dvh - 78px); place-content: center; padding: 40px 22px; text-align: center; } .back-action { margin: 35px auto 0; padding: 13px 20px; border: 0; border-radius: 13px; color: #f2fffc; background: #167f87; cursor: pointer; }
  .modal-mask { position: fixed; inset: 0; z-index: 10; display: grid; place-items: center; padding: 22px; background: rgba(31,77,84,.22); backdrop-filter: blur(8px); } .product-modal { position: relative; width: min(490px, 100%); padding: 31px; border: 1px solid rgba(255,255,255,.75); border-radius: 26px; background: rgba(250,255,253,.94); box-shadow: 0 25px 70px rgba(52,115,117,.19); } .modal-close { position: absolute; top: 17px; right: 18px; border: 0; color: #7e9b9d; background: transparent; cursor: pointer; font-size: 25px; } .product-modal h2 { margin: 0; color: #285963; font-size: 25px; letter-spacing: -.06em; } .product-modal p { margin: 8px 0 24px; color: #8aa3a4; font-size: 12px; } .product-modal label { display: block; margin-top: 14px; color: #60878a; font-size: 11px; } .product-modal input, .product-modal select, .product-modal textarea { display: block; width: 100%; margin-top: 7px; padding: 0 13px; border: 1px solid rgba(56,125,131,.15); border-radius: 12px; outline: none; color: #285963; background: rgba(255,255,255,.76); font: inherit; font-size: 13px; } .product-modal input, .product-modal select { height: 43px; } .product-modal textarea { padding-top: 11px; resize: vertical; } .product-modal input:focus, .product-modal select:focus, .product-modal textarea:focus { border-color: #55b6a7; box-shadow: 0 0 0 3px rgba(85,182,167,.12); } .save-product { width: 100%; height: 45px; margin-top: 23px; border: 0; border-radius: 13px; color: #effffc; background: #167f87; cursor: pointer; font-size: 13px; font-weight: 700; }
